def max_path_sum(nodes: list) -> int:
    if not nodes or nodes[0] is None:
        return 0
    max_sum = -float('inf')
    def post_order(idx):
        nonlocal max_sum
        if idx >= len(nodes) or nodes[idx] is None:
            return 0
        left = max(0, post_order(2 * idx + 1))
        right = max(0, post_order(2 * idx + 2))
        max_sum = max(max_sum, nodes[idx] + left + right)
        return nodes[idx] + max(left, right)
    post_order(0)
    return max_sum
